-- ═══════════════════════════════════════════════════════════════════════════
-- Phase 2 Migration 3 — RI-05 ReadingIndex PARTITION BY RANGE (calculatedAt)
-- ═══════════════════════════════════════════════════════════════════════════
--
-- @prisma-skip-generate
-- ╔═════════════════════════════════════════════════════════════════════════╗
-- ║ RAW SQL MIGRATION — NOT generated by prisma migrate dev.                 ║
-- ║                                                                          ║
-- ║ Converts ReadingIndex from a heap table to a PostgreSQL native           ║
-- ║ range-partitioned table by month, with 16 initial partitions covering   ║
-- ║ the prior 13 months + current month + next 2 months.                    ║
-- ║                                                                          ║
-- ║ Prisma's schema continues to model ReadingIndex as a regular table —     ║
-- ║ that is intentional. PG routes inserts/selects transparently across     ║
-- ║ partitions; Prisma operations work unchanged. The Phase 1 composite     ║
-- ║ index @@index([userId, calculatedAt]) lives on the parent and PG ≥ 11   ║
-- ║ auto-propagates it to every existing and future partition.              ║
-- ║                                                                          ║
-- ║ DO NOT regenerate this migration. If it ever needs amending, the safe   ║
-- ║ workflow is `prisma migrate dev --create-only --name <new>` followed by ║
-- ║ a hand edit before `prisma migrate dev` applies.                        ║
-- ║                                                                          ║
-- ║ Data preservation: an existing ReadingIndex row count of N rows is      ║
-- ║ preserved via temp-table rename + INSERT INTO. PG routes each row to    ║
-- ║ the correct partition by calculatedAt. The old heap table is dropped   ║
-- ║ only AFTER the INSERT completes successfully.                          ║
-- ╚═════════════════════════════════════════════════════════════════════════╝

-- ── Step 1: rename existing heap table ──────────────────────────────────────
-- The Phase-1 composite index ReadingIndex_userId_calculatedAt_idx is renamed
-- along with its parent table by PG (indexes always follow their table on
-- RENAME). The FK ReadingIndex_userId_fkey is also carried along.
ALTER TABLE "ReadingIndex" RENAME TO "ReadingIndex_old";

-- The above rename also renames the indexes/constraints to keep them attached
-- to the renamed table. Explicitly rename them so the new partitioned table
-- can re-use the canonical names without collision.
ALTER INDEX "ReadingIndex_pkey" RENAME TO "ReadingIndex_old_pkey";
ALTER INDEX "ReadingIndex_userId_calculatedAt_idx"
    RENAME TO "ReadingIndex_old_userId_calculatedAt_idx";
ALTER TABLE "ReadingIndex_old"
    RENAME CONSTRAINT "ReadingIndex_userId_fkey" TO "ReadingIndex_old_userId_fkey";

-- ── Step 2: create the new partitioned parent ───────────────────────────────
-- PG requires the partition key to be part of every UNIQUE / PRIMARY KEY
-- constraint, so the composite PK becomes (id, calculatedAt) instead of just
-- id. Prisma's client only writes `id` — the calculatedAt default on the
-- column makes Prisma writes succeed without code changes.
CREATE TABLE "ReadingIndex" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "score" DOUBLE PRECISION NOT NULL,
    "components" JSONB NOT NULL,
    "calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ReadingIndex_pkey" PRIMARY KEY ("id", "calculatedAt")
) PARTITION BY RANGE ("calculatedAt");

-- ── Step 3: re-add the foreign key to User ──────────────────────────────────
-- Preserve the existing semantics (ON DELETE RESTRICT ON UPDATE CASCADE)
-- as captured from the live `\\d+ ReadingIndex` output prior to migration.
ALTER TABLE "ReadingIndex"
    ADD CONSTRAINT "ReadingIndex_userId_fkey"
    FOREIGN KEY ("userId") REFERENCES "User"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

-- ── Step 4: re-create the composite index on the parent ─────────────────────
-- PG ≥ 11 auto-propagates this index to every existing and future partition,
-- so this single CREATE replaces the Phase-1 orphan index.
CREATE INDEX "ReadingIndex_userId_calculatedAt_idx"
    ON "ReadingIndex"("userId", "calculatedAt");

-- ── Step 5: attach 16 monthly partitions ────────────────────────────────────
-- Covers [CURRENT_DATE - 13 months, CURRENT_DATE + 2 months]. The DO $$ block
-- is idempotent across the planning-to-deploy window because the boundaries
-- are computed from CURRENT_DATE at migration-apply time, not file-edit time.
-- Partition naming: ReadingIndex_yYYYY_mMM (e.g. ReadingIndex_y2026_m06).
DO $$
DECLARE
    i INT;
    start_month DATE;
    end_month DATE;
    partition_name TEXT;
BEGIN
    -- i goes from -13 (13 months ago) through +2 (2 months ahead) inclusive
    -- = 16 partitions total.
    FOR i IN -13..2 LOOP
        start_month := date_trunc('month', CURRENT_DATE + (i || ' month')::interval)::DATE;
        end_month   := start_month + INTERVAL '1 month';
        partition_name := 'ReadingIndex_y'
                          || to_char(start_month, 'YYYY')
                          || '_m'
                          || to_char(start_month, 'MM');
        EXECUTE format(
            'CREATE TABLE %I PARTITION OF "ReadingIndex" FOR VALUES FROM (%L) TO (%L);',
            partition_name,
            start_month,
            end_month
        );
    END LOOP;
END $$;

-- ── Step 6: copy existing data ──────────────────────────────────────────────
-- PG routes each row to the correct monthly partition by calculatedAt. If
-- ReadingIndex_old has rows with calculatedAt outside the [now - 13mo, now +
-- 2mo] window, the INSERT will fail with "no partition of relation found";
-- the rollback (Step 9) covers that case. As of 2026-06-06 the live dev DB
-- has 1 row; production deploy must verify the date range against the
-- partition window beforehand.
INSERT INTO "ReadingIndex" SELECT * FROM "ReadingIndex_old";

-- ── Step 7: drop the old heap table ─────────────────────────────────────────
-- CASCADE drops the carried-along indexes / FK that were renamed in Step 1.
DROP TABLE "ReadingIndex_old" CASCADE;

-- ═══════════════════════════════════════════════════════════════════════════
-- Step 9 — Rollback strategy (operator reference, NOT executed)
-- ═══════════════════════════════════════════════════════════════════════════
-- If this migration leaves the table half-converted (e.g. Step 6 INSERT
-- fails because a row's calculatedAt is outside the partition window), the
-- recovery path is:
--
--   1. Drop any partial new partitioned ReadingIndex:
--        DROP TABLE "ReadingIndex" CASCADE;
--   2. Restore the old heap table to its canonical name:
--        ALTER TABLE "ReadingIndex_old" RENAME TO "ReadingIndex";
--        ALTER INDEX "ReadingIndex_old_pkey" RENAME TO "ReadingIndex_pkey";
--        ALTER INDEX "ReadingIndex_old_userId_calculatedAt_idx"
--            RENAME TO "ReadingIndex_userId_calculatedAt_idx";
--        ALTER TABLE "ReadingIndex"
--            RENAME CONSTRAINT "ReadingIndex_old_userId_fkey"
--            TO "ReadingIndex_userId_fkey";
--   3. Mark the migration as rolled back:
--        npx prisma migrate resolve --rolled-back 20260607000002_phase2_ri_partitions
--
-- Forward-fix path (preferred):
--   1. Extend the partition range in the DO $$ block to cover the offending
--      rows (e.g. widen i from -24..2).
--   2. Re-run the migration on a clean DB or apply the fix incrementally.
-- ═══════════════════════════════════════════════════════════════════════════
